; =====================================================================
;  DISPLAY.ASM -- Q3 palette mock-up display
;
;  Screen layout (192 scan lines):
;    24 blank lines
;     2 x ANTIC mode 2  status bar  (ROM font, OS shadow colours)
;    11 x ANTIC mode 5  map         (mock-up font, colours set by DLI)
;
;  One map square = 2 mode 5 characters = 8 x 8 pixels, shown
;  8 colour clocks wide and 16 scan lines tall.  Font and screen data
;  come from MOCK_DATA.ASM (generated by tools/mkmock.py).
;
;  Sprites (D13 layout): P0 = player 1 cursor, missiles = fifth
;  player for weather.  A normal-width player is exactly one square;
;  the fifth player at double width is two squares.
; =====================================================================

MAPROWS =  11           ; mode 5 lines in the map zone

; ---------------------------------------------------------------------
;  Palette -- edit these to try other colours
; ---------------------------------------------------------------------
; Status bar (OS shadows)
C_SBAR  =  $82          ; status bar background (COLPF2)
C_STXT  =  $0E          ; status bar text luminance (COLPF1)
C_SBRD  =  $00          ; status bar border (COLBK)

; Map zone (DLI)
C_SEA   =  $84          ; COLBK  -- sea
C_GRASS =  $C6          ; COLPF0 -- grass
C_DARK  =  $00          ; COLPF1 -- black: fort, factory, crop, rebel, boats
C_LIGHT =  $1C          ; COLPF2 -- yellow: beach, house roof, smoke, sail
C_WHITE =  $0E          ; COLPF3 -- white: school, hospital, weather

; Sprites
C_CURS  =  $44          ; player 1 cursor (COLPM0)

; ---------------------------------------------------------------------
;  P/M graphics, double-line resolution, 1K at PMAREA
; ---------------------------------------------------------------------
PMAREA  =  $4000
PM_MIS  =  PMAREA+$180  ; missiles (fifth player)
PM_P0   =  PMAREA+$200  ; player 0
PM_MAP  =  24           ; P/M line of map row 0 (scan line 48 / 2)
HP_MAP  =  48           ; horizontal position of map column 0

; Mock-up sprite placement (map row, square column)
CU_ROW  =  3            ; cursor over the right island's rebel
CU_COL  =  15
WX_ROW  =  4            ; weather cloud over the left island
WX_COL  =  2

; ---------------------------------------------------------------------
;  DISP_INIT -- install display list, DLI, VBI and sprites.
;  Writes only RAM vectors, shadows and hardware; calls no OS routines.
; ---------------------------------------------------------------------
DISP_INIT
        LDA #0
        STA NMIEN       ; no VBI/DLI while vectors are patched
        STA SDMCTL
        STA DMACTL

        JSR PM_INIT

        LDA #<DLI_MAP
        STA VDSLST
        LDA #>DLI_MAP
        STA VDSLST+1

        LDA VVBLKD      ; chain to whatever deferred VBI was there
        STA OLDVBD
        LDA VVBLKD+1
        STA OLDVBD+1
        LDA #<VBI_D
        STA VVBLKD
        LDA #>VBI_D
        STA VVBLKD+1

        LDA #<DLIST
        STA SDLSTL
        LDA #>DLIST
        STA SDLSTH

        LDA #C_SBAR
        STA COLOR2
        LDA #C_STXT
        STA COLOR1
        LDA #C_SBRD
        STA COLOR4
        LDA #C_CURS
        STA PCOLR0
        LDA #ROMFONT
        STA CHBAS
        LDA #PRI_MAP+PRI_5TH
        STA GPRIOR

        LDA #DMA_NORM+DMA_PM
        STA SDMCTL
        LDA #NMI_VBI+NMI_DLI
        STA NMIEN
        RTS

; ---------------------------------------------------------------------
;  PM_INIT -- clear P/M memory, draw the cursor and one weather cloud
; ---------------------------------------------------------------------
PM_INIT
        LDA #>PMAREA
        STA PMBASE
        LDA #0
        TAX
PI_CLR  STA PMAREA+$100,X
        STA PMAREA+$200,X
        STA PMAREA+$300,X
        INX
        BNE PI_CLR

        LDX #7
PI_SHP  LDA CURSHP,X
        STA PM_P0+PM_MAP+[CU_ROW*8],X
        LDA WXSHP,X
        STA PM_MIS+PM_MAP+[WX_ROW*8],X
        DEX
        BPL PI_SHP

        LDA #HP_MAP+[CU_COL*8]
        STA HPOSP0
        LDA #HP_MAP+[WX_COL*8]  ; fifth player: M3 M2 M1 M0, left to right
        STA HPOSM3
        CLC
        ADC #4
        STA HPOSM2
        ADC #4
        STA HPOSM1
        ADC #4
        STA HPOSM0
        LDA #0
        STA SIZEP0      ; normal width = one square
        LDA #$55
        STA SIZEM       ; all missiles double width = two squares total
        LDA #GR_PM
        STA GRACTL
        RTS

; Cursor: square outline, one square
CURSHP  .BYTE $FF,$81,$81,$81,$81,$81,$81,$FF
; Rain cloud: cloud over falling drops, two squares wide
WXSHP   .BYTE $38,$7C,$FE,$FF,$7E,$00,$A5,$4A

; ---------------------------------------------------------------------
;  DLI_MAP -- switch font and colours for the map zone
; ---------------------------------------------------------------------
DLI_MAP
        PHA
        TXA
        PHA
        TYA
        PHA
        LDA #C_SEA
        LDX #C_GRASS
        LDY #C_DARK
        STA WSYNC
        STA COLBK
        STX COLPF0
        STY COLPF1
        LDA #C_LIGHT
        STA COLPF2
        LDA #C_WHITE
        STA COLPF3
        LDA #>MAPFONT
        STA CHBASE
        PLA
        TAY
        PLA
        TAX
        PLA
        RTI

; ---------------------------------------------------------------------
;  VBI_D -- deferred VBI: frame counter, keep attract mode off
; ---------------------------------------------------------------------
VBI_D
        INC FRAME
        LDA #0
        STA ATRACT
        JMP (OLDVBD)

; ---------------------------------------------------------------------
;  Status bar text (screen codes), 2 lines of 40
; ---------------------------------------------------------------------
STATUS1 .SBYTE " ACADIA - Q3 PALETTE MOCKUP             "
STATUS2 .SBYTE " 1FT 2FA 3CR 4SC 5HO 6HS 7RB 8PT 9FB    "

; ---------------------------------------------------------------------
;  Display variables
; ---------------------------------------------------------------------
FRAME   .BYTE 0

; =====================================================================
;  Fixed-address data: font ($3000) and map screen ($3400)
; =====================================================================
        .INCLUDE "mock_data.asm"

; ---------------------------------------------------------------------
;  Display list
; ---------------------------------------------------------------------
        *= $3800
DLIST
        .BYTE DL_BLANK8,DL_BLANK8,DL_BLANK8
        .BYTE DL_LMS+DL_MODE2
        .WORD STATUS1
        .BYTE DL_DLI+DL_MODE2           ; DLI fires at end of this line
        .BYTE DL_LMS+DL_MODE5
        .WORD MAPSCR
        .BYTE DL_MODE5,DL_MODE5,DL_MODE5,DL_MODE5,DL_MODE5
        .BYTE DL_MODE5,DL_MODE5,DL_MODE5,DL_MODE5,DL_MODE5
        .BYTE DL_JVB
        .WORD DLIST
